<?php
require_once 'functions.php';require_role(['pelanggan']);$cart=active_cart($pdo,(int)user()['id_user']);
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';$did=(int)($_POST['id_detail']??0);
 if($action==='hapus')$pdo->prepare("DELETE d FROM tbl_detail_keranjang d JOIN tbl_keranjang k ON k.id_keranjang=d.id_keranjang WHERE d.id_detail_keranjang=? AND k.id_user=?")->execute([$did,user()['id_user']]);
 if($action==='ubah'){ $qty=max(1,(int)$_POST['jumlah']);$pdo->prepare("UPDATE tbl_detail_keranjang d JOIN tbl_keranjang k ON k.id_keranjang=d.id_keranjang SET d.jumlah=?,d.subtotal=?*d.harga WHERE d.id_detail_keranjang=? AND k.id_user=?")->execute([$qty,$qty,$did,user()['id_user']]);}
 flash('Keranjang diperbarui.');go('keranjang.php');}
$s=$pdo->prepare("SELECT d.*,p.nama_produk,p.foto,p.stok,p.jenis_produk FROM tbl_detail_keranjang d JOIN tbl_produk p ON p.id_produk=d.id_produk JOIN tbl_keranjang k ON k.id_keranjang=d.id_keranjang WHERE k.id_keranjang=?");$s->execute([$cart]);$items=$s->fetchAll();$total=array_sum(array_column($items,'subtotal'));
layout_header('Keranjang');
?>
<div class="page-title"><div><span class="eyebrow">BELANJA KAMU</span><h1>Keranjang belanja</h1><p>Periksa produk dan jumlah sebelum checkout.</p></div></div>
<?php if(!$items):?><div class="empty"><h2>Keranjang masih kosong</h2><p>Yuk temukan produk yang kamu butuhkan.</p><a class="btn btn-primary" href="index.php">Mulai belanja</a></div><?php else:?>
<div class="cart-layout"><div class="panel"><?php foreach($items as $it):?><div class="cart-item"><img src="<?=e(product_image($it['foto']))?>" alt=""><div class="cart-desc"><strong><?=e($it['nama_produk'])?></strong><small><?=rupiah($it['harga'])?> / item</small><b><?=rupiah($it['subtotal'])?></b></div><form method="post" class="qty-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="ubah"><input type="hidden" name="id_detail" value="<?=$it['id_detail_keranjang']?>"><input type="number" name="jumlah" min="1" value="<?=$it['jumlah']?>"><button class="btn btn-outline btn-sm">Ubah</button></form><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="hapus"><input type="hidden" name="id_detail" value="<?=$it['id_detail_keranjang']?>"><button class="btn btn-danger btn-sm">Hapus</button></form></div><?php endforeach;?></div><aside class="panel summary"><h3>Ringkasan belanja</h3><div class="summary-row"><span>Jumlah produk</span><b><?=count($items)?></b></div><div class="summary-row"><span>Subtotal</span><b><?=rupiah($total)?></b></div><div class="summary-total"><span>Total</span><strong><?=rupiah($total)?></strong></div><a class="btn btn-primary full" href="checkout.php">Lanjut Checkout</a><a class="btn btn-outline full" href="index.php">Tambah Produk</a></aside></div><?php endif;?>
<?php layout_footer(); ?>
